import type { ErrorRequestHandler } from "express";
import { Prisma } from "@prisma/client";
import { AppError } from "@eventflow/common/errors/app-error";
import { logger } from "@eventflow/common";

type ErrorResponse = {
  success: false;
  error: {
    code: string;
    message: string;
  };
};

export const errorHandler: ErrorRequestHandler = (error, _req, res, _next) => {
  const response = mapError(error);
  res.status(response.statusCode).json(response.body);
};

function mapError(error: unknown): {
  statusCode: number;
  body: ErrorResponse;
} {
  if (error instanceof AppError && error.isOperational) {
    return {
      statusCode: error.statusCode,
      body: {
        success: false,
        error: { code: error.code, message: error.message },
      },
    };
  }

  if (error instanceof Prisma.PrismaClientKnownRequestError) {
    const mapped = mapPrismaError(error);
    return {
      statusCode: mapped.statusCode,
      body: {
        success: false,
        error: { code: mapped.code, message: mapped.message },
      },
    };
  }

  logger.error({ err: error }, "Error no controlado en API Gateway");
  return {
    statusCode: 500,
    body: {
      success: false,
      error: {
        code: "INTERNAL_SERVER_ERROR",
        message: "Ocurrió un error interno del servidor",
      },
    },
  };
}

function mapPrismaError(error: Prisma.PrismaClientKnownRequestError): {
  statusCode: number;
  code: string;
  message: string;
} {
  switch (error.code) {
    case "P2002":
      return {
        statusCode: 409,
        code: "CONFLICT",
        message: "El recurso ya existe",
      };
    case "P2003":
      return {
        statusCode: 409,
        code: "FOREIGN_KEY_CONFLICT",
        message: "La operación viola una relación existente",
      };
    case "P2025":
      return {
        statusCode: 404,
        code: "NOT_FOUND",
        message: "El recurso solicitado no existe",
      };
    default:
      return {
        statusCode: 400,
        code: "DATABASE_ERROR",
        message: "No se pudo completar la operación de base de datos",
      };
  }
}
